# SecretReference: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Secretreference:
    ref_id: str = None  # Unique ID
    name: str = None  # Secret name
    vault_path: str = None  # Vault path
    version: float = None  # Version
    rotated_at: str = None  # Last rotation

REQUIRED = ["ref_id", "name", "vault_path", "version"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'ref_id': 'SEC-DB-01', 'name': 'prod/db/password', 'vault_path': 'secret/prod/db', 'version': 14, 'rotated_at': '2026-05-20T00:00:00Z'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

